/**
 * Shared structured log-entry parser/formatter for the L1 Automated Triage
 * health canary.
 *
 * This module is intentionally pure (no AWS SDK calls, no I/O) so it can be
 * reused both by the canary at emit time and by the DevOps Agent's
 * log-extraction step (Triage Skill step 1) at read time.
 *
 * A health-check log entry captures the outcome of a single HTTP GET against
 * one target URL:
 *
 *   {
 *     "l1tHealthCheck": true,
 *     "url": "https://svc.example.com/health/status",
 *     "status": "SUCCESS" | "FAILED" | "TIMEOUT" | "CREDENTIAL_FAILURE",
 *     "statusCode": 200 | null,
 *     "responseBody": "…" | null,
 *     "latencyMs": 123 | null,
 *     "timestamp": "2026-01-15T02:00:00.000Z"
 *   }
 */

'use strict';

/** Marker property that identifies an L1 triage health-check log entry. */
const HEALTH_CHECK_MARKER = 'l1tHealthCheck';

/** Recognized health-check outcome statuses. */
const STATUS = Object.freeze({
    SUCCESS: 'SUCCESS',
    FAILED: 'FAILED',
    TIMEOUT: 'TIMEOUT',
    CREDENTIAL_FAILURE: 'CREDENTIAL_FAILURE',
});

/** Maximum number of characters of a response body retained in a log entry. */
const MAX_RESPONSE_BODY_CHARS = 2048;

/**
 * Classify an HTTP status code into a health-check outcome status.
 *
 * @param {number} statusCode HTTP status code
 * @returns {string} STATUS.SUCCESS for 2xx, otherwise STATUS.FAILED
 */
function classifyStatusCode(statusCode) {
    if (typeof statusCode === 'number' && statusCode >= 200 && statusCode <= 299) {
        return STATUS.SUCCESS;
    }
    return STATUS.FAILED;
}

/**
 * Truncate a response body to the retained maximum length.
 *
 * @param {*} body raw response body (any type)
 * @returns {string|null} truncated string, or null when absent
 */
function truncateBody(body) {
    if (body === undefined || body === null) {
        return null;
    }
    const asString = typeof body === 'string' ? body : String(body);
    return asString.length > MAX_RESPONSE_BODY_CHARS ? asString.slice(0, MAX_RESPONSE_BODY_CHARS) : asString;
}

/**
 * Build a normalized, structured health-check log entry.
 *
 * Tolerates missing fields: any absent numeric/string field is emitted as
 * null so downstream consumers can detect and report gaps rather than crash.
 *
 * When a redirect chain is supplied, `status` (if not explicit) is derived
 * from the FINAL status code — a bare 3xx is neither pass nor fail on its own;
 * the caller follows redirects and reports the final status here.
 *
 * @param {object} input
 * @param {string} input.url the originally requested URL (required)
 * @param {string} [input.finalUrl] the final URL after following redirects
 * @param {string} [input.status] explicit status; otherwise derived from statusCode
 * @param {number} [input.statusCode] final HTTP status code, if a response was received
 * @param {*} [input.responseBody] response body or error text
 * @param {number} [input.latencyMs] measured latency in milliseconds
 * @param {Array<{url:string,statusCode:number,location:string}>} [input.redirectChain] redirect hops followed
 * @param {string} [input.timestamp] ISO 8601 timestamp; defaults to now
 * @returns {object} normalized log entry
 */
function formatLogEntry(input) {
    const source = input || {};
    const url = typeof source.url === 'string' && source.url.length > 0 ? source.url : null;

    let status = source.status;
    if (!status) {
        if (typeof source.statusCode === 'number') {
            status = classifyStatusCode(source.statusCode);
        } else {
            status = STATUS.TIMEOUT;
        }
    }

    const redirectChain = Array.isArray(source.redirectChain) ? source.redirectChain : [];

    return {
        [HEALTH_CHECK_MARKER]: true,
        url,
        finalUrl: typeof source.finalUrl === 'string' && source.finalUrl.length > 0 ? source.finalUrl : url,
        status,
        statusCode: typeof source.statusCode === 'number' ? source.statusCode : null,
        responseBody: truncateBody(source.responseBody),
        latencyMs: typeof source.latencyMs === 'number' ? source.latencyMs : null,
        redirectCount: redirectChain.length,
        redirectChain,
        timestamp:
            typeof source.timestamp === 'string' && source.timestamp.length > 0
                ? source.timestamp
                : new Date().toISOString(),
    };
}

/**
 * Determine whether a parsed object is an L1 triage health-check entry.
 *
 * @param {*} entry candidate object
 * @returns {boolean}
 */
function isHealthCheckEntry(entry) {
    return Boolean(entry) && typeof entry === 'object' && entry[HEALTH_CHECK_MARKER] === true;
}

/**
 * Extract the salient fields from a health-check log entry for triage,
 * tolerating missing fields by reporting them in `missingFields`.
 *
 * Used by the agent's log-extraction step (step 1) to pull the failed URL,
 * status code, and response body out of a canary log line.
 *
 * @param {object|string} entry a log entry object or its JSON string form
 * @returns {{url: (string|null), statusCode: (number|null), timedOut: boolean, responseBody: (string|null), status: (string|null), missingFields: string[]}}
 */
function extractFields(entry) {
    let parsed = entry;
    if (typeof entry === 'string') {
        try {
            parsed = JSON.parse(entry);
        } catch (e) {
            return {
                url: null,
                statusCode: null,
                timedOut: false,
                responseBody: null,
                status: null,
                missingFields: ['url', 'statusCode', 'responseBody', 'status'],
            };
        }
    }

    const source = parsed && typeof parsed === 'object' ? parsed : {};
    const missingFields = [];

    const url = typeof source.url === 'string' && source.url.length > 0 ? source.url : null;
    if (url === null) {
        missingFields.push('url');
    }

    const status = typeof source.status === 'string' && source.status.length > 0 ? source.status : null;
    if (status === null) {
        missingFields.push('status');
    }

    const timedOut = status === STATUS.TIMEOUT;

    const statusCode = typeof source.statusCode === 'number' ? source.statusCode : null;
    // A timeout legitimately has no status code, so only flag it missing otherwise.
    if (statusCode === null && !timedOut) {
        missingFields.push('statusCode');
    }

    const responseBody =
        typeof source.responseBody === 'string' && source.responseBody.length > 0 ? source.responseBody : null;
    // A timeout legitimately has no response body, so only flag it missing otherwise.
    if (responseBody === null && !timedOut) {
        missingFields.push('responseBody');
    }

    return { url, statusCode, timedOut, responseBody, status, missingFields };
}

module.exports = {
    HEALTH_CHECK_MARKER,
    STATUS,
    MAX_RESPONSE_BODY_CHARS,
    classifyStatusCode,
    truncateBody,
    formatLogEntry,
    isHealthCheckEntry,
    extractFields,
};
